-- Fase 4 · bloque D, sesión 2: revisiones nuevas (borrador, inactivas) de I29C e I30C en el Catálogo y
-- en DEMO, con la tabla armada desde el lazo (M.1) o desde la causa C&E (E.1). Re-ejecutable: no crea
-- otra revisión si ya existe un borrador «Revisión F4-D». Activarlas es decisión del editor (Luis).
DO $$
DECLARE
  spec jsonb := '{"I29C": {"desc": "Revisión F4-D (2026-10-15): loop check por señal generado desde el lazo. La tabla M.1 se arma con las señales activas del lazo y su cadena (JB → marshalling → I/O → DCS → HMI) al generar el ITR; los equipos de prueba van en su sección (F4-B).", "rte": true, "sections": [{"title": "Referencias de ejecución", "items": [{"n": "R.1", "t": "text", "en": "Identification and revision of the drawings, specifications or procedure used for this inspection.", "es": "Identificación y revisión de los planos, especificaciones o procedimiento utilizados para esta inspección.", "req": true, "opts": null, "oo": {}}]}, {"title": "Inspección", "items": [{"n": "1.1", "t": "select", "en": "B check sheet(s) completed and signed.", "es": "Check sheet(s) «B» completada(s) y firmada(s).", "req": true, "opts": ["Conforme", "No conforme", "No aplica"], "oo": {"Conforme": "pass", "No conforme": "fail", "No aplica": "not_applicable"}}, {"n": "1.2", "t": "select", "en": "Preparation in field completed.", "es": "Preparación en campo completada.", "req": true, "opts": ["Conforme", "No conforme", "No aplica"], "oo": {"Conforme": "pass", "No conforme": "fail", "No aplica": "not_applicable"}}, {"n": "1.3", "t": "select", "en": "Configuration of relevant parameters in the control system.", "es": "Configuración de parámetros relevantes en el sistema de control.", "req": true, "opts": ["Conforme", "No conforme", "No aplica"], "oo": {"Conforme": "pass", "No conforme": "fail", "No aplica": "not_applicable"}}, {"n": "1.4", "t": "select", "en": "Loop drawing and I/O assignment verified against the as-built documentation.", "es": "Diagrama de lazo y asignación de I/O verificados contra la documentación as-built.", "req": true, "opts": ["Conforme", "No conforme", "No aplica"], "oo": {"Conforme": "pass", "No conforme": "fail", "No aplica": "not_applicable"}}]}, {"title": "Loop check por señal", "items": [{"n": "M.1", "t": "table", "en": "Loop check per signal: field → junction box → marshalling → I/O card/channel → DCS tag → HMI.", "es": "Loop check por señal: campo → caja de conexiones → marshalling → tarjeta/canal I/O → tag DCS → HMI.", "req": true, "opts": {"version": 2, "rows": {"mode": "source", "source": "loop_signals", "label": "Señal"}, "columns": [{"key": "signal_type", "label": "Tipo", "type": "reference", "unit": null, "options": null, "min": null, "max": null, "required": false, "ref": "signal_type"}, {"key": "range", "label": "Rango", "type": "reference", "unit": null, "options": null, "min": null, "max": null, "required": false, "ref": "range"}, {"key": "junction_box", "label": "JB", "type": "reference", "unit": null, "options": null, "min": null, "max": null, "required": false, "ref": "junction_box"}, {"key": "marshalling", "label": "Marshalling", "type": "reference", "unit": null, "options": null, "min": null, "max": null, "required": false, "ref": "marshalling"}, {"key": "io", "label": "Tarjeta I/O", "type": "reference", "unit": null, "options": null, "min": null, "max": null, "required": false, "ref": "io_card"}, {"key": "channel", "label": "Canal", "type": "reference", "unit": null, "options": null, "min": null, "max": null, "required": false, "ref": "io_channel"}, {"key": "dcs_tag", "label": "Tag DCS", "type": "reference", "unit": null, "options": null, "min": null, "max": null, "required": false, "ref": "dcs_tag"}, {"key": "hmi", "label": "HMI", "type": "reference", "unit": null, "options": null, "min": null, "max": null, "required": false, "ref": "hmi_display"}, {"key": "wiring", "label": "Cableado, continuidad y polaridad", "type": "result", "unit": null, "options": null, "min": null, "max": null, "required": true}, {"key": "injected", "label": "Valor aplicado", "type": "number", "unit": null, "options": null, "min": null, "max": null, "required": false}, {"key": "read", "label": "Lectura en DCS", "type": "number", "unit": null, "options": null, "min": null, "max": null, "required": false}, {"key": "hmi_ok", "label": "Indicación HMI y alarmas", "type": "result", "unit": null, "options": null, "min": null, "max": null, "required": true}, {"key": "result", "label": "Resultado", "type": "result", "unit": null, "options": null, "min": null, "max": null, "required": true}, {"key": "remarks", "label": "Observación", "type": "text", "unit": null, "options": null, "min": null, "max": null, "required": false}]}, "oo": {}}]}, {"title": "Observaciones", "items": [{"n": "O.1", "t": "text", "en": "Inspection remarks and references to findings recorded in the Punch List, where applicable.", "es": "Observaciones de la inspección y referencias a hallazgos registrados en Punch List, cuando correspondan.", "req": false, "opts": null, "oo": {}}]}]}, "I30C": {"desc": "Revisión F4-D (2026-10-15): prueba de una causa de la matriz C&E, generada desde la causa. La tabla E.1 se arma con los efectos que dispara la causa (acción y retardo esperados) al generar el ITR.", "rte": false, "sections": [{"title": "Referencias de ejecución", "items": [{"n": "R.1", "t": "text", "en": "Identification and revision of the drawings, specifications or procedure used for this inspection.", "es": "Identificación y revisión de los planos, especificaciones o procedimiento utilizados para esta inspección.", "req": true, "opts": null, "oo": {}}]}, {"title": "Datos de la causa", "items": [{"n": "D.1", "t": "text", "en": "Procedure or functional description applied.", "es": "Procedimiento o descripción funcional aplicada.", "req": false, "opts": null, "oo": {}}]}, {"title": "Prueba de la causa", "items": [{"n": "1.0", "t": "select", "en": "Loop checks of every device in the function are approved (C check sheets completed and signed).", "es": "La prueba de lazo de cada componente de la función está aprobada (check sheets «C» completadas y firmadas).", "req": true, "opts": ["Conforme", "No conforme", "No aplica"], "oo": {"Conforme": "pass", "No conforme": "fail", "No aplica": "not_applicable"}}, {"n": "2.0", "t": "select", "en": "Simulate or force the trip value of the initiator (cause) and verify the activation of the final elements (effects).", "es": "Simular o forzar el valor de disparo del iniciador (causa) y verificar la activación de los elementos finales (efectos).", "req": true, "opts": ["Conforme", "No conforme", "No aplica"], "oo": {"Conforme": "pass", "No conforme": "fail", "No aplica": "not_applicable"}}, {"n": "2.0-R", "t": "text", "en": "Trip value applied and unit, as per the cause set point.", "es": "Valor de disparo aplicado y unidad, según el set point de la causa.", "req": true, "opts": null, "oo": {}}, {"n": "2.1", "t": "select", "en": "Check operation of bypass switches (POS / MOS), if applicable.", "es": "Verificar funcionamiento de interruptores de desvío (POS / MOS), si aplica.", "req": true, "opts": ["Conforme", "No conforme", "No aplica"], "oo": {"Conforme": "pass", "No conforme": "fail", "No aplica": "not_applicable"}}, {"n": "2.2", "t": "select", "en": "Alarm and first-out annunciated in the DCS / HMI.", "es": "Alarma y primera salida (first-out) anunciadas en DCS / HMI.", "req": true, "opts": ["Conforme", "No conforme", "No aplica"], "oo": {"Conforme": "pass", "No conforme": "fail", "No aplica": "not_applicable"}}, {"n": "2.3", "t": "select", "en": "Final elements remain in the safe state until manual reset; the reset restores normal operation.", "es": "Los elementos finales permanecen en estado seguro hasta el reset manual; el reset restablece la operación normal.", "req": true, "opts": ["Conforme", "No conforme", "No aplica"], "oo": {"Conforme": "pass", "No conforme": "fail", "No aplica": "not_applicable"}}, {"n": "3.0", "t": "select", "en": "Apply the specific procedure for the interlock or safety instrumented function.", "es": "Aplicar el procedimiento específico del enclavamiento o función instrumentada de seguridad.", "req": true, "opts": ["Conforme", "No conforme", "No aplica"], "oo": {"Conforme": "pass", "No conforme": "fail", "No aplica": "not_applicable"}}]}, {"title": "Efectos de la causa", "items": [{"n": "E.1", "t": "table", "en": "Test of each effect triggered by the cause: action, response time and feedback.", "es": "Prueba de cada efecto que dispara la causa: acción, tiempo de respuesta y confirmación.", "req": true, "opts": {"version": 2, "rows": {"mode": "source", "source": "ce_effects", "label": "Efecto"}, "columns": [{"key": "description", "label": "Descripción", "type": "reference", "unit": null, "options": null, "min": null, "max": null, "required": false, "ref": "effect_description"}, {"key": "action", "label": "Acción esperada", "type": "reference", "unit": null, "options": null, "min": null, "max": null, "required": false, "ref": "action"}, {"key": "link", "label": "Cruce", "type": "reference", "unit": null, "options": null, "min": null, "max": null, "required": false, "ref": "link"}, {"key": "executed", "label": "Ejecutó la acción", "type": "select", "unit": null, "options": ["Sí", "No"], "min": null, "max": null, "required": true}, {"key": "response_s", "label": "Tiempo de respuesta", "type": "number", "unit": "s", "options": null, "min": null, "max": null, "required": false}, {"key": "feedback", "label": "Confirmación (feedback) en DCS", "type": "result", "unit": null, "options": null, "min": null, "max": null, "required": true}, {"key": "result", "label": "Resultado", "type": "result", "unit": null, "options": null, "min": null, "max": null, "required": true}, {"key": "remarks", "label": "Observación", "type": "text", "unit": null, "options": null, "min": null, "max": null, "required": false}]}, "oo": {}}]}, {"title": "Observaciones", "items": [{"n": "O.1", "t": "text", "en": "Inspection remarks and references to findings recorded in the Punch List, where applicable.", "es": "Observaciones de la inspección y referencias a hallazgos registrados en Punch List, cuando correspondan.", "req": false, "opts": null, "oo": {}}]}]}}'::jsonb;
  org record; v_code text; src public.itr_templates; new_id uuid; sec_id uuid; sec jsonb; item jsonb; si integer; ii integer; made text := '';
BEGIN
  FOR org IN SELECT id, name FROM public.organizations WHERE name IN ('CommUp Catálogo', 'DEMO Refinería Los Andes (AUTOTEST)') LOOP
    FOREACH v_code IN ARRAY ARRAY['I29C', 'I30C'] LOOP
      IF EXISTS (SELECT 1 FROM public.itr_templates WHERE org_id = org.id AND itr_templates.code = v_code AND description LIKE 'Revisión F4-D%') THEN CONTINUE; END IF;
      SELECT * INTO src FROM public.itr_templates t WHERE t.org_id = org.id AND t.code = v_code ORDER BY t.version DESC LIMIT 1;
      IF NOT FOUND THEN CONTINUE; END IF;
      INSERT INTO public.itr_templates (org_id, discipline_id, equipment_type_id, phase_id, code, title, title_es, description, version, is_active, is_global, requires_test_equipment)
      VALUES (org.id, src.discipline_id, src.equipment_type_id, src.phase_id, src.code, src.title, src.title_es, spec->v_code->>'desc',
              (SELECT max(version) + 1 FROM public.itr_templates WHERE org_id = org.id AND itr_templates.code = src.code), false, src.is_global, (spec->v_code->>'rte')::boolean)
      RETURNING id INTO new_id;
      si := 0;
      FOR sec IN SELECT value FROM jsonb_array_elements(spec->v_code->'sections') LOOP
        INSERT INTO public.itr_template_sections (template_id, title, order_index) VALUES (new_id, sec->>'title', si) RETURNING id INTO sec_id;
        ii := 0;
        FOR item IN SELECT value FROM jsonb_array_elements(sec->'items') LOOP
          INSERT INTO public.itr_template_items (template_id, section_id, item_number, item_type, description, description_es, is_required, is_critical, options, option_outcomes, order_index)
          VALUES (new_id, sec_id, item->>'n', (item->>'t')::public.itr_item_type, item->>'en', item->>'es', (item->>'req')::boolean, false,
                  CASE WHEN jsonb_typeof(item->'opts') = 'null' THEN NULL ELSE item->'opts' END, item->'oo', ii);
          ii := ii + 1;
        END LOOP;
        si := si + 1;
      END LOOP;
      made := made || org.name || ' ' || v_code || ' v' || (SELECT version FROM public.itr_templates WHERE id = new_id) || ' (' || new_id || '); ';
    END LOOP;
  END LOOP;
  RAISE NOTICE 'Creadas: %', made;
END $$;
